    Lemma miz_head : forall (k : nat) (i up dn : Z) x16,
      Z.to_nat (n - i) = k -> 0 <= i < n -> A + i < up ->
      up mod 8 = 0 -> A <= up < A + 8 -> dn mod 8 = 0 -> A + n - 8 < dn <= A + n -> 0 <= dn ->
